    { id: "s1", description: "Do something", success: true },
  ], ["src/file.ts"])
  gi_assert(prLong.title.length <= 75, "GI-3a long title truncated (≤75 chars)")
  gi_assert(prLong.title.endsWith("..."), "GI-3b long title ends with ellipsis")

